<script setup lang="ts">
import {computed} from 'vue';import {useEditor} from '../stores/editor';import {placementWarnings} from '../domain/furniture';import {clone,uid} from '../domain/project';
import type {FurnitureInstance} from '../domain/types';
const e=useEditor(),item=computed(()=>e.variant.furniture.find(f=>f.id===e.selected?.id)),warnings=computed(()=>item.value?placementWarnings(e.document,item.value):[]);
const fields=[['width','Ширина предмета, м'],['depth','Глубина предмета, м'],['height','Высота предмета, м'],['x','Положение X, м'],['z','Положение Z, м'],['y','Высота над полом, м'],['rotation','Поворот, °']] as const;
function change(fn:(f:FurnitureInstance)=>void){const id=item.value!.id;e.edit('Изменить мебель',p=>fn(p.variants.find(v=>v.id===p.activeVariantId)!.furniture.find(f=>f.id===id)!));}
function duplicate(){const copy=clone(item.value!);copy.id=uid();copy.name+=' — копия';copy.x+=.3;copy.z+=.3;if(e.edit('Копировать предмет',p=>p.variants.find(v=>v.id===p.activeVariantId)!.furniture.push(copy)))e.selected={kind:'furniture',id:copy.id};}
</script>
<template><section v-if="item" class="inspector-section"><div class="eyebrow">Предмет</div><h2>{{item.name}}</h2><label>Название предмета<input :value="item.name" @change="change(f=>f.name=($event.target as HTMLInputElement).value)"></label><label v-for="[key,label] in fields">{{label}}<input type="number" :step="key==='rotation'?15:.01" :value="item[key]" @change="change(f=>{f[key]=Number(($event.target as HTMLInputElement).value)})"></label><label>Цвет предмета<input type="color" :value="item.material.color" @change="change(f=>f.material.color=($event.target as HTMLInputElement).value)"></label><label class="check-label"><input type="checkbox" :checked="item.visible" @change="change(f=>f.visible=($event.target as HTMLInputElement).checked)">Показывать предмет</label><div v-if="warnings.length" class="warnings"><p v-for="warning in warnings">{{warning}}</p></div><button @click="duplicate">Копировать предмет</button><button class="danger" @click="e.removeSelected">Удалить предмет</button></section></template>
